+// API keys and roles. Keys live in the data as `apiKeys` ({ key, name,
+// role }); each role may do everything the roles before it may.
+import { createHash, timingSafeEqual } from "node:crypto";
+
+/** Roles from least to most allowed. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+const digest = (text) => createHash("sha256").update(text).digest();
+
+/** The API key record for `key`, or null when there is none. */
+export function findKey(store, key) {
+  if (typeof key !== "string" || key === "") return null;
+  const wanted = digest(key);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (typeof k.key !== "string" || k.key === "") continue;
+    if (timingSafeEqual(digest(k.key), wanted)) found ??= k;
+  }
+  return found;
+}
+
+/** Whether `role` may do what needs at least the role `needed`. */
+export function roleAllows(role, needed) {
+  const have = ROLES.indexOf(role);
+  const need = ROLES.indexOf(needed);
+  return have >= 0 && need >= 0 && have >= need;
+}
